import os

def word_count(directory):
    words = set()
    for filename in os.listdir(directory):
        with open(os.path.join(directory, filename), 'r') as f:
            for line in f:
                words.add(line.strip())

    counts = defaultdict(int)
    for word in words:
        counts[word] = word_count(directory, word)

    top_words = sorted(counts.items(), key=lambda x: x[1], reverse=True)[:5]
    return top_words

def word_count_in_file(file_name, words):
    with open(file_name, 'r') as f:
        for line in f:
            for word in words:
                if word in line.lower():
                    word_count(file_name, word)

def main():
    directory = '.'
    print(word_count(directory))

if __name__ == '__main__':
