def find_median(arr1, arr2):
    # Sort both arrays
    arr1 = sorted(arr1)
    arr2 = sorted(arr2)

    # Find the length of both arrays
    arr1_length = len(arr1)
    arr2_length = len(arr2)

    # Initialize the index of the median
    median_index = 0

    # Compare the first two elements
    if arr1_length < arr2_length:
        if arr1[0] < arr2[0]:
            median_index = 0
        else:
            median_index = 1

    # Compare the last two elements
    elif arr1_length > arr2_length:
        if arr2[arr2_length - 1] < arr1[arr1_length - 1]:
            median_index = arr1_length - 1
        else:
            median_index = arr2_length - 1

    # Swap the elements if the first array element is greater than the second array element
    if arr1[median_index] > arr2[0]:
        arr1[median_index], arr2[0] = arr2[0], arr1[median_index]

    return arr1[median_index]<s>

