def majority_element(arr):
    # Initialize the vote counter for each element
    vote_count = {}
    for i in range(len(arr)):
        vote_count[arr[i]] = 0

    # Count the votes for each element
    for i in range(len(arr)):
        if arr[i] in vote_count:
            vote_count[arr[i]] += 1
        else:
            vote_count[arr[i]] = 1

    # Find the majority element
    majority = arr[0]
    for i in range(1, len(arr)):
        if vote_count[majority] < vote_count[arr[i]]:
            majority = arr[i]

    # Return the majority element
    return majority<s>

